import Foundation

/// Pure ownership policy. This component never installs a notification-center
/// delegate. The application-owned delegate decides how to handle unmatched
/// notifications. Only identifiers generated by this timer namespace match.
public enum MacTimerPresentationPolicy {
    public static let identifierPrefix = "floe.mac.toolbox.timer."

    public static func owns(_ identifier: String) -> Bool {
        guard identifier.hasPrefix(identifierPrefix) else { return false }
        let suffix = identifier.dropFirst(identifierPrefix.count)
        let parts = suffix.split(separator: ".", omittingEmptySubsequences: false)
        guard (1...2).contains(parts.count), let id = UUID(uuidString: String(parts[0])),
              id.uuidString.caseInsensitiveCompare(String(parts[0])) == .orderedSame else { return false }
        if parts.count == 1 { return true } // historical timer request
        let generationText = String(parts[1])
        guard let generation = UInt64(generationText), String(generation) == generationText else { return false }
        return true
    }

    /// The host invokes this from its existing will-present callback. Unknown
    /// requests go to the host's original handler exactly once, unchanged.
    /// No delegate is installed or replaced by this function.
    public static func route<Result>(identifier: String,
                                     timer: () -> Result,
                                     fallback: (String) -> Result) -> Result {
        if owns(identifier) { return timer() }
        return fallback(identifier)
    }

}
